sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */



function handler({
    api,
    event,
    helpers,
    imports
}) {
    var {
        name,
        payload
    } = event;
    if (name === 'NOW_TYPEAHEAD_MULTI#SELECTED_ITEMS_SET') {
        if (event.elementId == 'supporting_data_fields') {
            if (payload.value) {
                var arr = [];
                payload.value.forEach(function(obj) {
                    arr.push(obj);
                });
                api.setState('supportingDataFields', arr);
            }
        }
    }

    //Searching fields based on initials
    if (name === "NOW_TYPEAHEAD_MULTI#VALUE_SET") {
        api.setState('fieldSearchString', payload.value);
    }

    let sampleSizeErrorMessageValue = '';

    if (name === 'NOW_INPUT#INPUT') {
        if (event.elementId == 'sample_size') {
            if (payload.fieldValue || api.state.sampleCollectionType == 'count') {
                api.setState('sampleSize', parseInt(payload.fieldValue));
            }

            if (api.state.sampleCollectionType == 'count' && parseInt(payload.fieldValue) <= 0) {
                sampleSizeErrorMessageValue = api.state.sampleCountErrorMessage;
            } else if (api.state.sampleCollectionType == 'percentage' && (!payload.fieldValue || (parseInt(payload.fieldValue) <= 0 || parseInt(payload.fieldValue) > 100))) {
                sampleSizeErrorMessageValue = api.state.samplePercentageErrorMessage;
            }

        }
    }

    if (name === 'NOW_SELECT#SELECTED_ITEM_SET') {
        if (event.elementId == 'sample_collection_type') {
            if (payload.item && payload.item.id) {

                if (payload.item.id === 'count') {
                    api.setState('isSampleSizeRequired', false);

                    if (api.state.sampleCollectionType == 'percentage') {
                        api.setState('sampleSizeDisplayLabel', api.state.sampleSizeLabel);

                    }

                    if (parseInt(api.state.sampleSize) <= 0) {
                        sampleSizeErrorMessageValue = api.state.sampleCountErrorMessage;
                    }
                }

                if (payload.item.id === 'percentage') {
                    api.setState('isSampleSizeRequired', true);

                    if (api.state.sampleCollectionType == 'count') {
                        api.setState('sampleSizeDisplayLabel', api.state.samplePercentageLabel);

                    }

                    if (api.state.sampleSize == null || isNaN(api.state.sampleSize) || parseInt(api.state.sampleSize) <= 0 || parseInt(api.state.sampleSize) > 100) {
                        sampleSizeErrorMessageValue = api.state.samplePercentageErrorMessage;
                    }
                }

                api.setState('sampleCollectionType', payload.item.id);

            }
        }
    }

    if (sampleSizeErrorMessageValue) {
        api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
            items: [{
                id: "record-alert-1",
                status: "critical",
                icon: "info-circle-outline",
                content: sampleSizeErrorMessageValue,
                action: {
                    type: "dismiss"
                }
            }]
        });
        api.setState('disableSave', true);
    } else {
        api.setState('disableSave', false);
    }

}
